import "@stdlib/exotic-cells"
import "constants"

// Transparent sparse sets used for duplicate commitments and spent nullifiers.
// The value zero is the empty-subtree sentinel; non-empty hashes are domain
// separated so the two sets cannot share witnesses.
const SPARSE_SET_COMMITMENT_DOMAIN: uint32 = 0x5a4b4301
const SPARSE_SET_NULLIFIER_DOMAIN: uint32 = 0x5a4b4e01
const SPARSE_SET_LEAF_TAG: uint8 = 1
const SPARSE_SET_NODE_TAG: uint8 = 2
const SPARSE_SET_BUCKET_BITS: int = 8
const SPARSE_SET_BUCKET_MASK: int = (1 << SPARSE_SET_BUCKET_BITS) - 1
const SPARSE_SET_DEPTH: int = 247
const SPARSE_SET_PROOF_BITS: int = 256 + SPARSE_SET_DEPTH
const SPARSE_SET_SIBLINGS_PER_CELL: int = 3

/// Canonical proof root. `siblings` is a packed chain ordered by increasing
/// tree level; its exact shape is validated by `sparseSetApplyUpdate`.
struct SparseSetUpdateProof {
    expectedRoot: uint256
    siblingBitmap: uint247
    siblings: cell
}

enum SparseSetUpdateStatus {
    Ok = 0
    InvalidDomain = 1
    InvalidKey = 2
    MalformedProof = 3
    StaleRoot = 4
    NonEmptyLeafOrInvalidWitness = 5
}

/// Runtime-only result. Pool handlers translate the status into their stable
/// deposit/withdraw error codes and persist `newRoot` only when status is Ok.
struct SparseSetUpdateResult {
    status: SparseSetUpdateStatus
    bucketId: uint8
    newRoot: uint256
    bucketWasPresent: bool = false
}

@pure
@inline
fun sparseSetIsKnownDomain(domain: uint32): bool {
    return domain == SPARSE_SET_COMMITMENT_DOMAIN || domain == SPARSE_SET_NULLIFIER_DOMAIN;
}

@pure
@inline
fun sparseSetBucketId(key: uint256): uint8 {
    return (key & SPARSE_SET_BUCKET_MASK) as uint8;
}

@pure
@inline
fun sparseSetPath(key: uint256): int {
    return key >> SPARSE_SET_BUCKET_BITS;
}

@pure
@inline
fun sparseSetLeafHash(domain: uint32, key: uint256): uint256 {
    return beginCell()
        .storeUint((domain << 8) | SPARSE_SET_LEAF_TAG, 40)
        .storeUint(key, 256)
        .hash();
}

@pure
@inline
fun sparseSetNonEmptyNodeHashWithHeader(
    header: uint48,
    left: uint256,
    right: uint256,
): uint256 {
    return beginCell().storeUint(header, 48).storeUint(left, 256).storeUint(right, 256).hash();
}

@pure
@inline
fun sparseSetNonEmptyNodeHash(
    domain: uint32,
    level: uint8,
    left: uint256,
    right: uint256,
): uint256 {
    val header = ((domain << 16) | (SPARSE_SET_NODE_TAG << 8) | level) as uint48;
    return sparseSetNonEmptyNodeHashWithHeader(header, left, right);
}

@pure
@inline
fun sparseSetIsCanonicalSiblingChunk(chunk: slice, isExotic: bool): bool {
    if (isExotic) {
        return false;
    }
    val bits = chunk.remainingBitsCount();
    val refs = chunk.remainingRefsCount();
    if (refs == 1) {
        return bits == SPARSE_SET_SIBLINGS_PER_CELL * 256;
    }
    return refs == 0 && bits <= SPARSE_SET_SIBLINGS_PER_CELL * 256 && bits % 256 == 0;
}

/// Verify an empty-leaf witness against `storedRoot` and return the only root
/// that can result from inserting `key`. The caller never supplies `newRoot`.
@pure
fun sparseSetApplyUpdate(
    domain: uint32,
    key: uint256,
    storedRoot: uint256,
    proofCell: cell,
): SparseSetUpdateResult {
    val bucketId = sparseSetBucketId(key);
    if (!sparseSetIsKnownDomain(domain)) {
        return {
            status: SparseSetUpdateStatus.InvalidDomain,
            bucketId,
            newRoot: 0,
        };
    }
    if (key >= BLS12_381_R) {
        return {
            status: SparseSetUpdateStatus.InvalidKey,
            bucketId,
            newRoot: 0,
        };
    }

    // check-disable-next-line mutable-variable-can-be-immutable
    var (proof, proofIsExotic) = proofCell.beginParseSpecial();
    if (
        proofIsExotic || proof.remainingBitsCount() != SPARSE_SET_PROOF_BITS ||
        proof.remainingRefsCount() != 1
    ) {
        return {
            status: SparseSetUpdateStatus.MalformedProof,
            bucketId,
            newRoot: 0,
        };
    }

    val expectedRoot = proof.loadUint(256);
    val siblingBitmap = proof.loadUint(SPARSE_SET_DEPTH);
    val siblingChain = proof.loadRef();
    if (expectedRoot != storedRoot) {
        return {
            status: SparseSetUpdateStatus.StaleRoot,
            bucketId,
            newRoot: 0,
        };
    }

    // The chain is validated while it is consumed. Every shape check happens
    // before a load, so malformed proofs return a status instead of throwing.
    // check-disable-next-line mutable-variable-can-be-immutable
    var (chain, chainIsExotic) = siblingChain.beginParseSpecial();
    if (!sparseSetIsCanonicalSiblingChunk(chain, chainIsExotic)) {
        return {
            status: SparseSetUpdateStatus.MalformedProof,
            bucketId,
            newRoot: 0,
        };
    }

    var oldRoot: uint256 = 0;
    var newRoot = sparseSetLeafHash(domain, key);
    var path = sparseSetPath(key);
    var bitmap = siblingBitmap;
    var level: uint8 = 0;
    val nodeDomainBuilder = beginCell().storeUint(
        (domain << 8) | SPARSE_SET_NODE_TAG,
        40,
    );

    repeat (SPARSE_SET_DEPTH) {
        var sibling: uint256 = 0;
        if ((bitmap & 1) != 0) {
            if (chain.remainingBitsCount() == 0) {
                if (chain.remainingRefsCount() != 1) {
                    return {
                        status: SparseSetUpdateStatus.MalformedProof,
                        bucketId,
                        newRoot: 0,
                    };
                }
                val nextChunk = chain.loadRef();
                // check-disable-next-line mutable-variable-can-be-immutable
                (chain, chainIsExotic) = nextChunk.beginParseSpecial();
                if (!sparseSetIsCanonicalSiblingChunk(chain, chainIsExotic)) {
                    return {
                        status: SparseSetUpdateStatus.MalformedProof,
                        bucketId,
                        newRoot: 0,
                    };
                }
                if (chain.remainingBitsCount() == 0) {
                    return {
                        status: SparseSetUpdateStatus.MalformedProof,
                        bucketId,
                        newRoot: 0,
                    };
                }
            }
            sibling = chain.loadUint(256);
            if (sibling == 0) {
                return {
                    status: SparseSetUpdateStatus.MalformedProof,
                    bucketId,
                    newRoot: 0,
                };
            }
        }

        var prefixBuilder = nodeDomainBuilder;
        prefixBuilder.storeUint(level, 8);
        if ((path & 1) == 0) {
            if (oldRoot != 0 || sibling != 0) {
                var oldBuilder = prefixBuilder;
                oldRoot = oldBuilder.storeUint(oldRoot, 256).storeUint(sibling, 256).hash();
            }
            var newBuilder = prefixBuilder;
            newRoot = newBuilder.storeUint(newRoot, 256).storeUint(sibling, 256).hash();
        } else {
            var leftPrefixBuilder = prefixBuilder;
            leftPrefixBuilder.storeUint(sibling, 256);
            if (oldRoot != 0 || sibling != 0) {
                var oldBuilder = leftPrefixBuilder;
                oldRoot = oldBuilder.storeUint(oldRoot, 256).hash();
            }
            var newBuilder = leftPrefixBuilder;
            newRoot = newBuilder.storeUint(newRoot, 256).hash();
        }

        path >>= 1;
        bitmap >>= 1;
        level += 1;
    }

    if (!chain.isEmpty()) {
        return {
            status: SparseSetUpdateStatus.MalformedProof,
            bucketId,
            newRoot: 0,
        };
    }

    if (oldRoot != storedRoot) {
        return {
            status: SparseSetUpdateStatus.NonEmptyLeafOrInvalidWitness,
            bucketId,
            newRoot: 0,
        };
    }

    return {
        status: SparseSetUpdateStatus.Ok,
        bucketId,
        newRoot,
    };
}

import "bls-helpers"
import "bls-scalar"
import "verifier-insert-vk" // auto-generated by scripts/vk-to-tolk.js

// Groth16 BLS12-381 verifier for the Merkle insertion circuit.
//
// Circuit (insert.circom) public inputs (in this order):
//   0. oldRoot          : root before insertion
//   1. newRoot          : root after inserting `commitment` at `leafIndex`
//   2. commitment       : the leaf being inserted
//   3. leafIndex        : position in the tree
//
// The VK constants live in `verifier-insert-vk.tolk` and are regenerated
// from `circuits/build/insert_*_vk.json` after each ceremony pass.

fun verifyInsertProof(
    oldRoot: uint256,
    newRoot: uint256,
    commitment: uint256,
    leafIndex: uint32,
    proofA: slice,
    proofB: slice,
    proofC: slice,
): bool {
    // Strict slice-shape gate. MUST run before any BLS opcode that reads
    // the slice: TVM 2023-07 silently truncates over-length inputs to
    // 48/96 bytes (G1/G2) and throws cell_underflow on under-length —
    // both surface as soundness or liveness defects without this guard.
    // Compressed BLST: G1 = 48 bytes = 384 bits, G2 = 96 bytes = 768 bits,
    // no refs in either case.
    if (proofA.remainingBitsCount() != 384 || proofA.remainingRefsCount() != 0) {
        return false;
    }
    if (proofB.remainingBitsCount() != 768 || proofB.remainingRefsCount() != 0) {
        return false;
    }
    if (proofC.remainingBitsCount() != 384 || proofC.remainingRefsCount() != 0) {
        return false;
    }

    // Public-input range check: reject inputs >= r so a malleated `x` and
    // `x + r` cannot collide as different uint256 storage keys while pairing
    // to the same scalar in Fr. `leafIndex: uint32` is trivially in range
    // and skipped.
    if (!blsScalarIsCanonical(oldRoot)) {
        return false;
    }
    if (!blsScalarIsCanonical(newRoot)) {
        return false;
    }
    if (!blsScalarIsCanonical(commitment)) {
        return false;
    }

    // Subgroup membership + non-zero check on prover-supplied points.
    // Without these, small-order torsion points and identity points can be
    // combined to forge Groth16 proofs (canonical malleability vector;
    // closed by every production verifier: snarkjs, gnark, ark).
    if (!blsG1InGroup(proofA) || !blsG2InGroup(proofB) || !blsG1InGroup(proofC)) {
        return false;
    }
    if (blsG1IsZero(proofA) || blsG2IsZero(proofB) || blsG1IsZero(proofC)) {
        return false;
    }

    var vkX = vkInsertIc(0);
    vkX = blsG1Add(vkX, blsG1Mul(vkInsertIc(1), oldRoot));
    vkX = blsG1Add(vkX, blsG1Mul(vkInsertIc(2), newRoot));
    vkX = blsG1Add(vkX, blsG1Mul(vkInsertIc(3), commitment));
    vkX = blsG1Add(vkX, blsG1Mul(vkInsertIc(4), leafIndex));

    val negA = blsG1Neg(proofA);
    return blsPairingCheck4(
        negA,
        proofB,
        vkInsertAlpha1(),
        vkInsertBeta2(),
        vkX,
        vkInsertGamma2(),
        proofC,
        vkInsertDelta2(),
    );
}

import "bls-helpers"
import "bls-scalar"
import "verifier-withdraw-vk" // auto-generated by scripts/vk-to-tolk.js

// Groth16 BLS12-381 verifier for the withdrawal circuit.
//
// Public inputs (in this order):
//   0. root             : must be a recently-known root of the pool
//   1. nullifierHash    : Poseidon(nullifier, 0)
//   2. recipientField   : recipient address as field element
//                         (lower 248 bits of address hash, derived in the
//                          handler from msg.recipient; see ADDRESS_FIELD_MASK)
//
// The transaction sender automatically receives RELAYER_REIMBURSEMENT; the
// relayer is NOT committed in the proof, so anyone may broadcast a published
// proof. The first to land wins; replays bounce on the nullifier check,
// refunding the loser's attached gas.

fun verifyWithdrawProof(
    root: uint256,
    nullifierHash: uint256,
    recipientField: uint256,
    proofA: slice,
    proofB: slice,
    proofC: slice,
): bool {
    // Strict slice-shape gate. MUST run before any BLS opcode that reads
    // the slice: TVM 2023-07 silently truncates over-length inputs to
    // 48/96 bytes (G1/G2) and throws cell_underflow on under-length —
    // both surface as soundness or liveness defects without this guard.
    // Compressed BLST: G1 = 48 bytes = 384 bits, G2 = 96 bytes = 768 bits,
    // no refs in either case.
    if (proofA.remainingBitsCount() != 384 || proofA.remainingRefsCount() != 0) {
        return false;
    }
    if (proofB.remainingBitsCount() != 768 || proofB.remainingRefsCount() != 0) {
        return false;
    }
    if (proofC.remainingBitsCount() != 384 || proofC.remainingRefsCount() != 0) {
        return false;
    }

    // Public-input range check: reject inputs >= r so a malleated
    // `nullifierHash` and `nullifierHash + r` cannot bypass the spent-map
    // by hashing to different uint256 keys while pairing to the same Fr
    // scalar (direct double-spend vector). `recipientField` is masked to
    // 248 bits at the caller and is trivially in range.
    if (!blsScalarIsCanonical(root)) {
        return false;
    }
    if (!blsScalarIsCanonical(nullifierHash)) {
        return false;
    }

    // Subgroup membership + non-zero check on prover-supplied points.
    // Required for Groth16 soundness against small-order / identity point
    // forgery attacks.
    if (!blsG1InGroup(proofA) || !blsG2InGroup(proofB) || !blsG1InGroup(proofC)) {
        return false;
    }
    if (blsG1IsZero(proofA) || blsG2IsZero(proofB) || blsG1IsZero(proofC)) {
        return false;
    }

    var vkX = vkWithdrawIc(0);
    vkX = blsG1Add(vkX, blsG1Mul(vkWithdrawIc(1), root));
    vkX = blsG1Add(vkX, blsG1Mul(vkWithdrawIc(2), nullifierHash));
    vkX = blsG1Add(vkX, blsG1Mul(vkWithdrawIc(3), recipientField));

    val negA = blsG1Neg(proofA);
    return blsPairingCheck4(
        negA,
        proofB,
        vkWithdrawAlpha1(),
        vkWithdrawBeta2(),
        vkX,
        vkWithdrawGamma2(),
        proofC,
        vkWithdrawDelta2(),
    );
}

// Thin asm wrappers for the BLS12-381 TVM opcodes.
//
// All four primitives are native TVM instructions (see `acton doc tvm BLS_*`).
// We expose them as pure Tolk functions so the verifier code stays readable.
//
// BLS12-381 point encodings follow the BLST compressed format:
//   - G1 points: 48 bytes (384 bits)
//   - G2 points: 96 bytes (768 bits)

/// # Safety
/// `x` and `y` must be valid BLS12-381 G1 points in BLST compressed
/// encoding (48 bytes / 384 bits each). Callers MUST length-check inputs
/// to exactly 384 bits and validate subgroup membership + non-identity
/// before calling, as TVM silently truncates over-length inputs and
/// throws `cell_underflow` on under-length — both are soundness defects
/// without the caller-side gate.
@pure
fun blsG1Add(x: slice, y: slice): slice
    asm "BLS_G1_ADD"

/// # Safety
/// `x` must be a valid G1 point (see blsG1Add). `scalar` is any 256-bit
/// integer; the TVM handles modular reduction internally.
@pure
fun blsG1Mul(x: slice, scalar: int): slice
    asm "BLS_G1_MUL"

/// # Safety
/// `x` must be a valid G1 point (see blsG1Add).
@pure
fun blsG1Neg(x: slice): slice
    asm "BLS_G1_NEG"

// Subgroup check. TVM's BLS opcodes validate that a point lies on the
// curve but do NOT verify it belongs to the prime-order subgroup; without
// this check, a prover can craft pairings using small-order torsion points.
/// # Safety
/// Returns true iff `x` is on the curve AND in the prime-order subgroup.
@pure
fun blsG1InGroup(x: slice): bool
    asm "BLS_G1_INGROUP"

/// # Safety
/// Returns true iff `x` is on the curve AND in the prime-order subgroup G2.
@pure
fun blsG2InGroup(x: slice): bool
    asm "BLS_G2_INGROUP"

// Identity check. e(0_G1, anything) = 1_GT collapses the pairing, which is
// a known forgery vector — a zero point is trivially in the subgroup, so
// INGROUP alone is insufficient.
/// # Safety
/// Returns true iff `x` encodes the identity element of G1.
@pure
fun blsG1IsZero(x: slice): bool
    asm "BLS_G1_ISZERO"

/// # Safety
/// Returns true iff `x` encodes the identity element of G2.
@pure
fun blsG2IsZero(x: slice): bool
    asm "BLS_G2_ISZERO"

// Multi-pairing check. Returns true iff the product of pairings equals 1
// in F_p12. For Groth16, n = 4:
//   e(-A, B) * e(alpha, beta) * e(vk_x, gamma) * e(C, delta) == 1
/// # Safety
/// All eight slices must be valid points in alternating G1/G2 groups.
@pure
fun blsPairingCheck4(
    a1: slice,
    a2: slice,
    b1: slice,
    b2: slice,
    c1: slice,
    c2: slice,
    d1: slice,
    d2: slice,
): bool
    asm "4 PUSHINT BLS_PAIRING"

import "constants"

@pure
@inline
fun blsScalarIsCanonical(value: uint256): bool {
    return value < BLS12_381_R;
}
